material.text:
{
  "name": "ctyun",
  "version": "0.1.0",
  "description": "天翼云 息壤 (eaichat.ctyun.cn) provider for magpie and OpenCode: API key sign-in, OpenAI-compatible chat completions; magpie converts to Anthropic Messages for Claude Code",
  "type": "module",
  "main": "./index.mjs",
  "files": [
    "index.mjs",
    "README.md"
  ],
  "keywords": [
    "magpie",
    "opencode",
    "opencode-plugin",
    "ctyun",
    "天翼云",
    "息壤"
  ],
  "license": "MIT",
  "scripts": {
    "test": "node --test test/plugin.test.mjs"
  },
  "magpie": {
    "name": "天翼云 息壤",
    "icon": "data:image/png;base64,",
    "maxConcurrency": 4,
    "summary": {
      "en": "Unofficial 天翼云 息壤 (CTyun Ecloud) access with your console API key: OpenAI-compatible chat completions at eaichat.ctyun.cn and the console's model list; magpie converts to Anthropic Messages for Claude Code.",
      "zh": "非官方天翼云 息壤接入：用控制台的 API Key 调用 eaichat.ctyun.cn 的 OpenAI 兼容接口，内置控制台快捷接入里的模型清单；Claude Code 等客户端由 magpie 自动转协议，无需第二个供应商。"
    }
  }
}
